/* Minimal touch launcher for j7elte: Xlib + cairo, no GTK/Qt. */
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <cairo/cairo.h>
#include <cairo/cairo-xlib.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define W 720
#define H 1280
#define COLS 2
#define ROWS 3

static const char *labels[ROWS][COLS] = {
	{ "Terminal", "Keyboard" },
	{ "Wi-Fi scan", "Reboot" },
	{ "Poweroff", "About" },
};
static const char *cmds[ROWS][COLS] = {
	{ "xterm -geometry 80x40+0+0 -bg white -fg black",
	  "xvkbd -geometry 700x260-10+1010" },
	{ "xterm -e 'nmcli device wifi list; sleep 30'",
	  "reboot" },
	{ "poweroff", "xterm -e 'uname -a; ip -4 a; sleep 30'" },
};

static Display *dpy;
static Window win;
static cairo_surface_t *surf;

static void draw(void)
{
	cairo_t *cr = cairo_create(surf);
	int x, y, w = W / COLS, h = (H - 120) / ROWS;

	cairo_set_source_rgb(cr, 0.05, 0.05, 0.07);
	cairo_paint(cr);

