        void *h = dlopen("libshadow.so", RTLD_NOW | RTLD_GLOBAL);
        if (!h)
            h = dlopen("/usr/lib/xorg/modules/libshadow.so", RTLD_NOW | RTLD_GLOBAL);
        if (h)
