		cairo_set_font_size(cr, 30);
		rgba(cr, "#e8eaed");
		cairo_move_to(cr, x + 28, y + 150);
		cairo_show_text(cr, apps[i].label);
		cairo_set_font_size(cr, 22);
		rgba(cr, "#8b93a1");
		cairo_move_to(cr, x + 28, y + 190);
		cairo_show_text(cr, apps[i].cmd);
	}

