		if (touch_fd >= 0) { FD_SET(touch_fd, &fds); if (touch_fd > maxfd) maxfd = touch_fd; }
		if (key_fd >= 0) { FD_SET(key_fd, &fds); if (key_fd > maxfd) maxfd = key_fd; }
