static int getCameraInfo(int cameraId, struct camera_info *info) {
    if(cameraId < 0 || cameraId >= getNumberOfCameras()) {
        ALOGE("%s: invalid camera ID (%d)", __FUNCTION__, cameraId);
        return -ENODEV;
