			if (!IS_ERR_OR_NULL(s)) {
				int pr = pinctrl_select_state(module->pdata->pinctrl, s);
				info("sensor I2C handed to ISP (pin1): %d\\n", pr);
			} else {
				info("pinctrl state pin1 not found\\n");
			}
		}
	}'''
